const maxScores:Record<string,number>=scoringMax;
const specialName:Record<string,string>=scoringSpecial;
const names:any={feeling:'活动感想',thinking:'活动思考',response:'应变能力',dialogue:'情景对话',impression:'综合印象',work:'工作理解',scene:'工作情景',photography:'摄影评价',intro:'开场介绍',survey:'其他调查',closing:'结束确认',availability:'到场确认'};
